const fs = require('fs');
const https = require('https');

// Read npm audit output
const auditData = JSON.parse(fs.readFileSync('/logs/agent/sessions/projects/-root/599f380b-570e-465b-a689-cb259f853738/tool-results/toolu_vrtx_01HmmSxiV3yNRz5MpQJz48Qm.txt', 'utf8'));

// Read package-lock.json to get installed versions
const packageLock = JSON.parse(fs.readFileSync('/root/package-lock.json', 'utf8'));

// Function to get installed version from package-lock.json
function getInstalledVersion(packageName) {
  // Check in packages first (npm v7+)
  if (packageLock.packages) {
    for (const [path, pkg] of Object.entries(packageLock.packages)) {
      if (path === `node_modules/${packageName}` || path.endsWith(`/node_modules/${packageName}`)) {
        return pkg.version;
      }
    }
  }

  // Fallback to dependencies (npm v6)
  if (packageLock.dependencies && packageLock.dependencies[packageName]) {
    return packageLock.dependencies[packageName].version;
  }

  return 'N/A';
}

// Function to fetch CVE ID from GHSA advisory
async function getCVEFromGHSA(ghsaUrl) {
  return new Promise((resolve) => {
    const ghsaId = ghsaUrl.split('/').pop();
    const apiUrl = `https://api.github.com/advisories/${ghsaId}`;

    https.get(apiUrl, {
      headers: {
        'User-Agent': 'Node.js Security Audit',
        'Accept': 'application/vnd.github+json'
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const advisory = JSON.parse(data);
          const cveId = advisory.cve_id || 'N/A';
          resolve(cveId);
        } catch (e) {
          resolve('N/A');
        }
      });
    }).on('error', () => resolve('N/A'));
  });
}

// Process vulnerabilities
async function processVulnerabilities() {
  const results = [];

  for (const [pkgName, vuln] of Object.entries(auditData.vulnerabilities)) {
    // Only process HIGH and CRITICAL severity
    if (vuln.severity !== 'high' && vuln.severity !== 'critical') {
      continue;
    }

    const installedVersion = getInstalledVersion(pkgName);

    // Process each vulnerability source
    if (Array.isArray(vuln.via)) {
      for (const via of vuln.via) {
        if (typeof via === 'object' && via.source) {
          // This is a direct vulnerability with details
          const cvssScore = via.cvss?.score || 0;
          const fixedVersion = vuln.fixAvailable
            ? (typeof vuln.fixAvailable === 'object' ? vuln.fixAvailable.version : 'Available')
            : 'N/A';

          results.push({
            package: pkgName,
            version: installedVersion,
            ghsaUrl: via.url,
            severity: via.severity.toUpperCase(),
            cvssScore: cvssScore,
            fixedVersion: fixedVersion,
            title: via.title,
            url: via.url
          });
        }
      }
    }
  }

  // Fetch CVE IDs for all GHSA advisories
  console.log('Fetching CVE IDs from GitHub advisories...');
  const resultsWithCVE = [];

  for (let i = 0; i < results.length; i++) {
    const result = results[i];
    console.log(`Processing ${i + 1}/${results.length}: ${result.package}`);

    const cveId = await getCVEFromGHSA(result.ghsaUrl);
    resultsWithCVE.push({
      ...result,
      cveId
    });

    // Add small delay to avoid rate limiting
    await new Promise(resolve => setTimeout(resolve, 200));
  }

  return resultsWithCVE;
}

// Main execution
(async () => {
  try {
    const vulnerabilities = await processVulnerabilities();

    // Create CSV content
    const csvHeader = 'Package,Version,CVE_ID,Severity,CVSS_Score,Fixed_Version,Title,Url\n';
    const csvRows = vulnerabilities.map(v => {
      // Escape fields that might contain commas
      const escapeField = (field) => {
        if (field === null || field === undefined) return '';
        const str = String(field);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
          return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
      };

      return [
        escapeField(v.package),
        escapeField(v.version),
        escapeField(v.cveId),
        escapeField(v.severity),
        escapeField(v.cvssScore),
        escapeField(v.fixedVersion),
        escapeField(v.title),
        escapeField(v.url)
      ].join(',');
    });

    const csvContent = csvHeader + csvRows.join('\n');
    fs.writeFileSync('/root/security_audit.csv', csvContent);

    console.log(`\nCompleted! Found ${vulnerabilities.length} HIGH and CRITICAL vulnerabilities.`);
    console.log('Results written to /root/security_audit.csv');
  } catch (error) {
    console.error('Error:', error);
    process.exit(1);
  }
})();

